@Composable fun RankingBadge(rank: Int) {
  val (bg, fg) = when(rank) { 1 -> Color(0xFFFF5757) to Color.White; 2,3 -> Color(0xFFFFB800) to Color.White; else -> Color(0xFFF0F0F0) to Color(0xFF999999) }
  Box(Modifier.size(20.dp).clip(RoundedCornerShape(4.dp)).background(bg), contentAlignment = Center) { Text(rank.toString(), color = fg, style = MaterialTheme.typography.labelSmall) }
}

@Composable fun BookMetaRow(book: Book) {
  Row(verticalAlignment = CenterVertically) {
    Text(book.author, style = labelSmall, color = Gray600); Text(" · ", color = Gray400)
    Text(if (book.isCompleted) "完结" else "在更", style = labelSmall, color = if(book.isCompleted) Green else Red); Text(" · ", color = Gray400)
    Text("${book.wordCount/10000}万字", style = labelSmall, color = Gray600)
  }
}
